static double estimateTestDuration(int testCount, double avg, int forks) {
    int effectiveForks = Math.min(forks, testCount);
    return (testCount * avg) / effectiveForks;
}
for (int f : new int[]{1,2,4,8}) System.out.println("forks=" + f + ": " + estimateTestDuration(100, 0.5, f) + "s");

static boolean matchesFilter(String name, String include, String exclude) {
    String inRegex = include.replace('*', '.*');
    String exRegex = exclude.replace('*', '.*');
    return name.matches(inRegex) && !name.matches(exRegex);
}
