static String simulateQualityGate(double actual, double required) {
    if (actual < required) return "Rule violated for bundle: lines covered ratio is " + actual + "%, minimum is " + required + "%";
    return "PASSED";
}
for (double c : new double[]{85,75,80,60}) System.out.println(simulateQualityGate(c, 80));

static double aggregateOverallCoverage(Map<String,double[]> data) {
    double covered = 0, total = 0;
    for (double[] v : data.values()) { covered += v[0]; total += v[1]; }
    return 100.0 * covered / total;
}
Map<String,double[]> data = Map.of("core", new double[]{80,100}, "service", new double[]{150,200}, "app", new double[]{30,50});
System.out.println(aggregateOverallCoverage(data) + "%");

static boolean isFlaky(boolean[] results) {
    boolean hasPass = false, hasFail = false;
    for (boolean r : results) { if (r) hasPass = true; else hasFail = true; }
    return hasPass && hasFail;
}
System.out.println(isFlaky(new boolean[]{true,true,true,true}));
System.out.println(isFlaky(new boolean[]{false,false,false}));
