static int calculateOptimalForks(int cores, int testCount, double avg, double target) {
    int needed = (int) Math.ceil((testCount * avg) / target);
    return Math.min(needed, cores);
}
System.out.println(calculateOptimalForks(8, 100, 0.5, 10));

static void compareCoverageReports(Map<String,Double> before, Map<String,Double> after) {
    for (String k : before.keySet()) {
        if (after.containsKey(k) && after.get(k) < before.get(k)) {
            System.out.println("POGORSZENIE: " + k + " " + before.get(k) + "% -> " + after.get(k) + "%");
        }
    }
}

record TestCase(String name, double seconds) {}
static void distributeAcrossForks(List<TestCase> tests, int forkCount) {
    double[] loads = new double[forkCount];
    List<List<String>> assignment = new ArrayList<>();
    for (int i = 0; i < forkCount; i++) assignment.add(new ArrayList<>());
    tests.stream().sorted((a,b) -> Double.compare(b.seconds(), a.seconds())).forEach(t -> {
        int minIdx = 0;
        for (int i = 1; i < forkCount; i++) if (loads[i] < loads[minIdx]) minIdx = i;
        loads[minIdx] += t.seconds();
        assignment.get(minIdx).add(t.name());
    });
    for (int i = 0; i < forkCount; i++) System.out.println("Worker " + i + ": " + assignment.get(i) + " = " + loads[i] + "s");
}

